import * as M from './model.js?v=20261009-views-1';
import {gateway, allowed} from './cloud.js?v=20261009-data-3';

const $ = s => document.querySelector(s);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const copy = value => JSON.parse(JSON.stringify(value));
const number = value => value === '' || value == null ? null : Number(value);
const total = list => list.reduce((a,b) => a + (Number(b) || 0), 0);
const records = kind => kind === 'recruiting' ? (Array.isArray(draft.recruiting) ? draft.recruiting : draft.recruiting?.rows || []) : draft[kind] || [];
const setRecords = (kind,rows) => {if(kind!=='recruiting'){draft[kind]=rows;return;}draft.recruiting=M.recruitingSummary({...(!Array.isArray(draft.recruiting)&&draft.recruiting||{}),rows});};
const fmt = (v, digits = 0) => v == null || !Number.isFinite(Number(v)) ? '—' : Number(v).toLocaleString('ko-KR', {maximumFractionDigits:digits});
const avgFmt = v => v == null || !Number.isFinite(Number(v)) ? '—' : Number(v).toLocaleString('ko-KR',{minimumFractionDigits:2,maximumFractionDigits:2});
const pct = v => v == null ? 'N/A' : `${fmt(v,1)}%`;
const money = v => v == null ? '—' : `${fmt(v)}원`;
const ratio = (a,b) => a != null && b > 0 ? a/b*100 : null;
const newId = () => globalThis.crypto?.randomUUID?.() || `recap-${Date.now()}-${Math.random().toString(36).slice(2)}`;
const chapters = [['PERFORMANCE','팀 세일즈 분석'],['RECRUITING','팀 리쿠르팅 분석'],['QUALITY CONTROL','팀원 QC · In & Out'],['WIN & HOW','Win & HOW'],['CHALLENGES','챌린지 & 개선 액션'],['LEARNING PLAN','러닝 플랜'],['TEAM TREE','팀 트리'],['PROMOTION GOAL','프로모션 골'],['OVERVIEW','전체 종합']];
const views = [{id:'sales',c:0,title:'세일즈 오버뷰'},{id:'weekly',c:0,title:'주차별 실적'},{id:'income',c:0,title:'인컴 랭킹'},{id:'recruit',c:1,title:'리쿠르팅 퍼널'},{id:'rank',c:1,title:'리쿠르팅 랭킹'},{id:'qc',c:2,title:'In · Out & 유지'},{id:'wins',c:3,title:'Win & HOW'},{id:'challenges',c:4,title:'챌린지 & 개선 액션'},{id:'callback',c:5,title:'콜백싯 제출률'},{id:'learning',c:5,title:'학습 & 다음 달 계획'},{id:'ic',c:5,title:'IC 성장 플랜'},{id:'tree',c:6,title:'팀 트리'},{id:'promotion',c:7,title:'프로모션 골'},{id:'overview',c:8,title:'전체 종합'}];
const params = new URLSearchParams(location.search);
const isViewer=location.pathname.endsWith('/recap-view.html');
if(!isViewer&&(params.has('published')||params.has('present'))){const target=new URL('recap-view.html',location.href);target.search=location.search;location.replace(target);}
const now = new Date();
const defaultMonth = `${now.getMonth() === 0 ? now.getFullYear()-1 : now.getFullYear()}-${String(now.getMonth() === 0 ? 12 : now.getMonth()).padStart(2,'0')}`;
let month = /^\d{4}-(0[1-9]|1[0-2])$/.test(params.get('month') || '') ? params.get('month') : defaultMonth;
let user, api, draft, liveSource, page = 0, dirty = false, saving = false, editing = false, presenting = false, readOnly = isViewer || params.has('published');
let pendingModal = null, dialogOrigin = null, noticeMessages = [], loadToken = 0, changeVersion = 0, toastTimer;
const view = () => views[page];
const monthName = () => `${month.slice(0,4)}년 ${Number(month.slice(5))}월`;
const knownIncome = () => (draft.members||[]).some(m=>(m.incomeWeeks||[]).some(v=>v!=null)) ? totals().knownIncome : null;
const missingIncome = () => (draft.members||[]).reduce((n,m)=>n+(m.incomeWeeks||[]).filter(v=>v==null).length,0);
const nextMonthName = () => {const dt = new Date(Number(month.slice(0,4)), Number(month.slice(5)), 1); return `${dt.getFullYear()}년 ${dt.getMonth()+1}월`;};
const backupKey = () => `presence-recap-keynote:${user?.uid || user?.id || user?.name}:${month}`;
const metrics = m => {
  const a = M.memberMetric(m);
  return {...a, rate:a.rejectRate ?? a.rate ?? null, raw:a.rawReject ?? a.raw ?? null, alert:(a.rejectRate ?? a.rate ?? 0) > 35};
};
const totals = () => {const a = M.totals(draft); return {...a,rate:a.rejectRate ?? a.rate ?? null,weeks:a.weekly ?? a.weeks ?? []};};
const callbackRows = () => (draft.members || []).map(m => ({...m,days:Number(m.days)||0,submitted:number(draft.callbacks?.[m.id]),rate:ratio(number(draft.callbacks?.[m.id]),Number(m.days)||0)}));
const callbackSummary = () => {const rows=callbackRows();const days=total(rows.map(r=>r.days)),submitted=total(rows.map(r=>r.submitted)),missing=rows.filter(r=>r.days>0&&r.submitted==null).length;return {rows,days,submitted,rate:missing?null:ratio(submitted,days),missing};};
const sortedMembers = () => [...(draft.members||[])].sort((a,b)=>(metrics(b).sales||0)-(metrics(a).sales||0));
const bar = (value,max=100,color='') => `<div class="bar-track"><div class="bar-fill ${color}" style="width:${Math.max(0,Math.min(100,(Number(value)||0)/Math.max(1,max)*100))}%"></div></div>`;
const empty = (title,body,action='edit') => `<div class="empty"><strong>${esc(title)}</strong><span>${esc(body)}</span>${(!readOnly||action==='retry-load')&&!presenting?`<button data-action="${action}">내용 입력하기</button>`:''}</div>`;
const kpi = (label,value,sub='',cls='') => `<div class="kpi ${cls}"><span>${esc(label)}</span><b>${esc(value)}</b><small>${esc(sub)}</small></div>`;
const tag = (text,cls='') => text ? `<span class="tag ${cls}">${esc(text)}</span>` : '';
const textBox = (title,text) => `<div class="text-box"><h3>${esc(title)}</h3><p>${esc(text||'아직 기록하지 않았습니다.')}</p></div>`;
const table = (heads,rows,foot='') => `<div class="table-wrap"><table class="data-table"><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody>${foot?`<tfoot>${foot}</tfoot>`:''}</table></div>`;
const person = m => `<b class="${metrics(m).alert?'danger':''}">${esc(m.name)}</b><span class="role">${esc(m.role||'')}</span>`;
const desc = {sales:'팀 전체 실적과 개인별 성과를 함께 확인합니다. 리젝률 35% 초과는 이름과 수치를 빨간색으로 표시합니다.',weekly:'월간 리캡에 포함된 급여 주차별 세일즈 추이입니다.',income:'급여 주차에 입력된 인컴 기준입니다. 미입력 주차는 0원으로 확정하지 않습니다.',recruit:'약속부터 참석, 신규 시작까지. 실제 입력한 리쿠르팅 수치를 기록합니다.',rank:'부킹 · 쇼업 · 스타터 기준의 개인별 리쿠르팅 실적입니다.',qc:'팀원의 합류와 이탈, 그리고 유지에 도움이 된 행동을 기록합니다.',wins:'좋은 결과를 만든 방법을 남기고, 다음 달에도 반복합니다.',challenges:'어려웠던 점을 실행 가능한 개선 액션으로 연결합니다.',callback:'콜백싯 제출 횟수 ÷ 필드일수. 팀 전체 제출률은 필드일수로 가중해 계산합니다.',learning:'IC · 트레이너 · 네트워킹. 지난달의 배움과 다음 달의 실행을 함께 남깁니다.',ic:'실제 첫 5일 성과와 5가지 역량을 바탕으로 3일 성장 플랜을 만듭니다.',tree:'워크북의 팀 관계를 기준으로 이달의 팀 구성과 영입 계획을 정리합니다.',promotion:'선택한 팀원의 목표 역할과 준비 과정을 기록합니다.',overview:'한 달의 숫자, 배운 점, 다음 달의 집중 과제를 한 화면에 모았습니다.'};

function renderSales(){
  const t=totals(), members=sortedMembers(), max=Math.max(1,...members.map(m=>metrics(m).sales||0));
  return `<div class="kpis">${kpi('팀 세일즈',fmt(t.sales),'월간 합계','featured')}${kpi('AVG',avgFmt(t.avg),'총 세일즈 ÷ 총 필드일수')}${kpi(t.incomeComplete===false?'확인된 인컴':'팀 인컴',money(t.incomeComplete===false?knownIncome():t.income),t.incomeComplete===false?`미입력 급여 기록 ${missingIncome()}개`:'급여 주차 합산')}${kpi('리젝률',pct(t.rate),'리젝은 리섭 차감 후 기준',t.rate>35?'danger':'')}</div>`+
    (members.length?table(['팀원','세일즈','필드','AVG','리젝','리젝률','인컴'],members.map(m=>{const a=metrics(m);return `<tr><td>${person(m)}</td><td><div class="bar-cell">${bar(a.sales,max)}<b>${fmt(a.sales)}</b></div></td><td>${fmt(a.days)}일</td><td>${avgFmt(a.avg)}</td><td>${fmt(a.reject)}</td><td class="${a.alert?'danger':''}">${pct(a.rate)}</td><td>${money(a.income)}${a.incomeComplete===false?' <small title="일부 급여 주차 미입력">*</small>':''}</td></tr>`;}),`<tr><td>팀 합계</td><td>${fmt(t.sales)}</td><td>${fmt(t.days)}일</td><td>${avgFmt(t.avg)}</td><td>${fmt(t.reject)}</td><td class="${t.rate>35?'danger':''}">${pct(t.rate)}</td><td>${money(t.incomeComplete===false?knownIncome():t.income)}${t.incomeComplete===false?' *':''}</td></tr>`):empty('이달 워크북 기록이 없습니다.','문서 메뉴에서 워크북 수치를 새로 불러올 수 있습니다.','refresh'))+
    `<p class="table-note">급여일 ${esc(draft.weeks?.[0]?.pay||'미확인')} ~ ${esc(draft.weeks?.at(-1)?.pay||'미확인')} · 필드 집계 ${esc(draft.weeks?.[0]?.start||'미확인')} ~ ${esc(draft.weeks?.at(-1)?.end||'미확인')}<br>— = 확인할 수 없는 값 · 인컴 * = 일부 주차 미입력 · ${esc(draft.notes?.sales||'리젝은 리섭 차감 후 기준')}</p>`;
}
function weekLabels(){return (draft.weeks||[]).map((w,i)=>({label:`W${i+1}`,date:typeof w==='string'?w:`필드 ${[w.start||w.startDate,w.end||w.endDate].filter(Boolean).join(' ~ ')}${w.pay?` / 급여일 ${w.pay}`:''}`,raw:w}));}
function renderWeekly(){
  const weeks=weekLabels(), members=sortedMembers(), sums=weeks.map((_,i)=>total(members.map(m=>m.scores?.[i]))), max=Math.max(1,...sums);
  if(!weeks.length)return empty('주차 기록이 없습니다.','워크북 수치를 불러오면 주차별 실적이 표시됩니다.','refresh');
  return `<div class="panel"><h3>주차별 팀 세일즈</h3><div class="week-bars">${weeks.map((w,i)=>`<div class="week-bar"><strong>${fmt(sums[i])}</strong><i style="height:${Math.max(2,sums[i]/max*165)}px"></i><span>${w.label}</span></div>`).join('')}</div></div><p class="table-note">${weeks.map(w=>`${w.label} ${esc(w.date)}`).join(' · ')}</p><div style="height:22px"></div>`+table(['팀원',...weeks.map(w=>w.label),'합계'],members.map(m=>`<tr><td>${person(m)}</td>${weeks.map((w,i)=>`<td>${fmt(m.scores?.[i])}</td>`).join('')}<td><b>${fmt(metrics(m).sales)}</b></td></tr>`),`<tr><td>팀 합계</td>${sums.map(s=>`<td>${fmt(s)}</td>`).join('')}<td>${fmt(total(sums))}</td></tr>`);
}
function renderIncome(){
  const t=totals(), members=[...(draft.members||[])].sort((a,b)=>(metrics(b).income??-1)-(metrics(a).income??-1)), max=Math.max(1,...members.map(m=>metrics(m).income||0));
  return `<div class="split"><section class="panel"><h3>팀원 인컴 랭킹</h3><div class="income-rank">${members.map((m,i)=>{const a=metrics(m);return `<div class="rank-row"><span class="rank-num">${String(i+1).padStart(2,'0')}</span><b class="${a.alert?'danger':''}">${esc(m.name)}</b>${bar(a.income,max,i===0?'':'pale')}<strong>${money(a.income)}${a.incomeComplete===false?' *':''}</strong></div>`;}).join('')||'<p>입력된 팀원이 없습니다.</p>'}</div></section><section class="panel income-summary"><div><span class="eyebrow">${t.incomeComplete===false?'확인된 인컴':'TEAM INCOME'}</span><div class="big-money">${money(t.incomeComplete===false?knownIncome():t.income)}</div><p>입력된 급여 주차의 합계입니다.<br>${t.incomeComplete===false?`미입력 급여 기록 ${missingIncome()}개가 있어 최종 인컴은 달라질 수 있습니다.`:'개인별 상세 기준은 워크북에서 확인합니다.'}</p></div><div class="badge-art" aria-hidden="true"><img src="assets/recap-keynote/growth-podium.png" alt="" style="width:100%;height:100%;object-fit:contain;position:absolute"><svg style="visibility:hidden" viewBox="0 0 80 80" fill="none"><path d="M16 61V42h12v19M34 61V29h12v32M52 61V15h12v46" fill="#477CFA"/><path d="m15 27 18-8 13 1 17-14m-1 0v12" stroke="#91B5FF" stroke-width="5" stroke-linecap="round"/></svg></div></section></div><p class="table-note">${weekLabels().map(w=>`${w.label} ${esc(w.date)}`).join(' · ')}<br>* 일부 급여 주차가 미입력되어 있습니다.</p>`;
}
function recruiting(){const r=M.recruitingSummary(draft.recruiting);return {...r,rows:r.rows,booked:r.booking,starters:r.starter};}
function renderRecruit(rank=false){const r=recruiting();return (rank?'':`<div class="funnel">${[['BOOKING',r.booked,'부킹'],['SHOW UP',r.showup,'쇼업'],['STARTER',r.starters,'스타터']].map(([en,n,ko])=>`<div class="funnel-step"><small>${en}</small><b>${fmt(n)}</b><p>${ko}</p></div>`).join('')}</div><div class="mini-kpis"><div><span>부킹 → 쇼업</span><b>${pct(ratio(r.showup,r.booked))}</b></div><div><span>쇼업 → 스타터</span><b>${pct(ratio(r.starters,r.showup))}</b></div></div>`)+(r.rows.length?table([rank?'랭킹 · 팀원':'팀원','부킹','쇼업','스타터'],[...r.rows].sort((a,b)=>b.starters-a.starters||b.showup-a.showup||b.booked-a.booked).map((r,i)=>`<tr><td>${rank?`<span class="role">${i+1}</span> `:''}<b>${esc(r.name)}</b></td><td>${fmt(r.booked)}</td><td>${fmt(r.showup)}</td><td><b>${fmt(r.starters)}</b></td></tr>`),`<tr><td>팀 합계</td><td>${fmt(r.booked)}</td><td>${fmt(r.showup)}</td><td>${fmt(r.starters)}</td></tr>`):empty('리쿠르팅 실적을 입력해 주세요.','편집에서 팀원을 선택하고 부킹 · 쇼업 · 스타터를 기록합니다.'))+textBox('리쿠르팅 회고',draft.notes?.recruit);}
function renderQC(){const events=draft.events||[],ins=events.filter(e=>e.type==='In').length,outs=events.length-ins,start=number(draft.qc?.startCount);return `<div class="flow-line"><div><small>월초 인원</small><b>${fmt(start)}</b></div><span>+</span><div><small>In</small><b>${ins}</b></div><span>−</span><div><small>Out</small><b>${outs}</b></div><span>=</span><div><small>월말 인원</small><b>${start==null?'—':fmt(start+ins-outs)}</b></div></div>`+(events.length?table(['팀원','일자','구분','사유 · 후속 액션','담당자'],events.map(e=>`<tr><td><b>${esc(e.name)}</b></td><td>${esc(e.date||'미입력')}</td><td>${tag(e.type,e.type==='In'?'green':e.type==='Out · 확인 필요'?'gold':'')}</td><td style="text-align:left;max-width:310px">${esc(e.reason||'사유 미입력')}<br><small>${esc(e.action||'')}</small></td><td>${esc(e.owner||'미지정')}</td></tr>`)):empty('이달의 In · Out 기록이 없습니다.','합류와 이탈을 추가하고, 이탈 사유는 Quit · Cut으로 구분해 기록합니다.'))+`<div class="split">${textBox('유지에 도움이 된 WIN',draft.qc?.retentionWin)}${textBox('교육 · 유지 활동 HOW',draft.qc?.trainingHow)}</div>`;}
function renderStories(type){const items=draft[type]||[],win=type==='wins';return items.length?`<div class="story-grid">${items.map((s,i)=>`<article class="story"><span class="story-index">${win?'WIN':'ACTION'} ${String(i+1).padStart(2,'0')}</span><h3>${esc(s.title||'제목 없음')}</h3><dl>${(win?[['WIN',s.win],['HOW',s.how],['NEXT',s.next]]:[['CAUSE',s.cause],['ACTION',s.action],['RESULT',s.result]]).map(([k,v])=>`<dt>${k}</dt><dd>${esc(v||'아직 기록하지 않았습니다.')}</dd>`).join('')}</dl>${!win?`<div class="story-meta">${tag(s.owner||'담당 미지정')}${tag(s.due||'기한 미지정')}${tag(s.status||'계획','green')}</div>`:''}</article>`).join('')}</div>`:empty(win?'이번 달의 성공을 기록해 주세요.':'개선할 과제와 다음 액션을 기록해 주세요.',win?'무엇을 잘했는지, 어떻게 했는지, 다음에 무엇을 반복할지 남깁니다.':'원인 · 액션 · 담당자 · 기한을 함께 정리합니다.');}
function renderCallback(){const s=callbackSummary(), groups=new Map();s.rows.forEach(r=>{const team=r.team||'팀 미지정';if(!groups.has(team))groups.set(team,[]);groups.get(team).push(r);});return `<div class="kpis">${kpi('팀 전체 제출률',s.missing?'입력 중':pct(s.rate),'총 제출 ÷ 총 필드일수','featured')}${kpi('콜백싯 제출',`${fmt(s.submitted)}회`,'입력된 제출 횟수 합계')}${kpi('총 필드일수',`${fmt(s.days)}일`,'월간 워크북 기준')}${kpi('미입력',`${s.missing}명`,'미입력과 0회는 구분합니다')}</div><div class="callback-teams">${[...groups].map(([name,rows])=>{const days=total(rows.map(r=>r.days)),submitted=total(rows.map(r=>r.submitted)),missing=rows.filter(r=>r.days>0&&r.submitted==null).length;return `<section class="team-callback"><div class="team-callback-header"><div><h3>${esc(name)}</h3><small>제출 ${submitted}회 / 필드 ${days}일 · ${rows.length}명</small></div><div class="team-gauge">${bar(missing?null:ratio(submitted,days))}<strong>${missing?'입력 중':pct(ratio(submitted,days))}</strong></div></div>${table(['팀원','필드일수','콜백싯 제출횟수','제출률'],rows.map(r=>`<tr><td><b>${esc(r.name)}</b><span class="role">${esc(r.role||'')}</span></td><td>${r.days}일</td><td><input class="callback-input" type="number" min="0" max="${r.days}" step="1" inputmode="numeric" data-callback="${esc(r.id)}" value="${r.submitted??''}" placeholder="미입력" aria-label="${esc(r.name)} 콜백싯 제출 횟수" ${readOnly||presenting||!r.days?'disabled':''}></td><td><div class="callback-output">${bar(r.submitted==null?null:r.rate)}<b>${!r.days?'해당 없음':r.submitted==null?'미입력':pct(r.rate)}</b></div></td></tr>`))}</section>`;}).join('')||empty('필드 기록이 있는 팀원이 없습니다.','워크북 수치를 불러오면 팀별 이행률을 입력할 수 있습니다.','refresh')}</div><p class="table-note">미입력이 남아 있으면 전체·팀 제출률을 확정하지 않습니다. 모두 입력하면 총 제출 횟수 ÷ 총 필드일수로 계산합니다. 필드 0일은 해당 없음입니다.</p>`;}
function renderLearning(){return `<div style="display:flex;justify-content:flex-end;height:54px;margin-top:-16px;margin-bottom:12px"><img src="assets/recap-keynote/learning-crest.png" alt="" style="width:72px;height:64px;object-fit:contain" aria-hidden="true"></div><div class="learn-lanes">${['IC','트레이너','네트워킹'].map(track=>`<section class="learn-lane"><h3>${track}</h3><small>${track==='IC'?'기초 역량 · 3일 성장 플랜':track==='트레이너'?'COD · 코칭 · 교육 운영':'1 on 1 · 관계 · 인사이트'}</small>${['지난달 회고','다음달 계획'].map(period=>`<div style="margin-top:22px">${tag(period,period==='다음달 계획'?'green':'')}${(draft.learning||[]).filter(x=>x.track===track&&x.period===period).map(x=>`<article class="learn-item"><h4>${esc(x.title||'제목 없음')}</h4><p>${esc(x.action||'실행 내용 미입력')}</p>${x.result?`<p style="margin-top:10px">${esc(x.result)}</p>`:''}<small>${esc([x.owner,x.due,x.status].filter(Boolean).join(' · ')||'담당자 · 일정 미입력')}</small></article>`).join('')||'<p class="table-note">아직 기록하지 않았습니다.</p>'}</div>`).join('')}</section>`).join('')}</div>`;}
const abilities=[['relate','릴레이트'],['booth','부스 컨트롤'],['pitch','피치 능력'],['objection','오브젝션 대응력'],['agreement','약정서 숙련도']];
function icMembers(){return allPeople().filter(m=>/\bIC\b/i.test(m.role||'')||Object.hasOwn(draft.icPlans||{},m.id));}
function renderIC(){const members=icMembers();return members.length?`<div class="ic-grid">${members.map(m=>{const p=draft.icPlans?.[m.id]||{},days=m.firstFive||[];return `<article class="ic-card"><div class="ic-heading"><div class="avatar" aria-hidden="true">${esc(m.name?.slice(0,1))}</div><div><h3>${esc(m.name)}</h3><small>${esc(m.team||'팀 미지정')} · ${esc(m.role||'IC')}</small></div></div><div class="five-days">${Array.from({length:5},(_,i)=>`<div title="${esc(days[i]?.date||'첫 5일 데이터 미확인')}"><small>D${i+1}</small><b>${fmt(days[i]?.sales)}</b></div>`).join('')}</div>${abilities.map(([key,label])=>`<div class="ability" style="grid-template-columns:minmax(100px,124px) 1fr 45px"><span>${label}${key==='pitch'?'<small style="display:block;font-size:12px;line-height:1.5">Tone of Voice · Body Language</small>':''}</span>${bar(p[key],5,'pale')}<b>${p[key]==null?'미평가':`${fmt(p[key])}/5`}</b></div>`).join('')}<div class="ic-focus"><b>이번 달 집중 역량</b><br>${esc(p.focus||'아직 설정하지 않았습니다.')}<br><br>${[1,2,3].map(n=>`<b>DAY ${n}</b> ${esc(p[`day${n}`]||'계획 미입력')}`).join('<br>')}</div></article>`;}).join('')}</div>`:empty('IC 성장 플랜을 준비해 주세요.','편집에서 실제 팀원을 선택하고 역량과 3일 플랜을 입력합니다.');}
function renderTree(){const nodes=draft.tree||[],ids=new Set(nodes.map(n=>n.id)), roots=nodes.filter(n=>!n.parent||!ids.has(n.parent));const renderNode=(node,seen=new Set(),root=false)=>{if(seen.has(node.id))return '';const next=new Set([...seen,node.id]);const children=nodes.filter(n=>n.parent===node.id);return `<div class="org-branch"><div class="org-node ${root?'root':''} ${node.planned?'planned':''}"><strong>${esc(node.name||'New IC')}</strong><small>${esc(node.role||'IC')}${node.planned?' · 추가 예정':''}</small>${!readOnly&&!presenting?`<button data-edit-only data-action="tree-add" data-id="${esc(node.id)}" aria-label="${esc(node.name)} 아래 팀원 추가">+</button>`:''}</div>${children.length?`<div class="org-children">${children.map(c=>renderNode(c,next)).join('')}</div>`:''}</div>`;};return `<div class="tree-head"><p class="tree-legend">실선: 기존 팀원 · 점선: New IC 추가 예정<br>이달의 트리 편집은 워크북 인사 정보에 반영되지 않습니다.</p>${!readOnly&&!presenting?'<button data-edit-only data-action="tree-add">＋ 팀원 추가</button>':''}</div>`+(roots.length?`<div class="org"><div class="org-children" style="padding-top:0">${roots.map(n=>renderNode(n,new Set(),true)).join('')}</div></div>`:empty('기준 팀 트리를 불러오지 못했습니다.','편집에서 워크북 원본을 다시 불러오거나 실제 팀원을 추가해 주세요.','edit'));}
function renderPromotion(){const rows=draft.promotions||[];return rows.length?`<div class="promotion-grid">${rows.map(p=>{const m=(draft.members||[]).find(m=>m.id===p.memberId)||(draft.roster||[]).find(m=>m.id===p.memberId);return `<article class="promotion"><div class="promotion-top"><div class="avatar" aria-hidden="true">↗</div><div><span class="eyebrow">NEXT ROLE</span><h3>${esc(m?.name||p.name||'팀원 확인 필요')}</h3><div class="promotion-path">${esc(m?.role||'현재 역할 미확인')} → ${esc(p.targetRole||'목표 역할 미입력')}</div></div></div><div class="promotion-body"><p>${esc(p.action||'준비 액션을 기록해 주세요.')}</p><div class="checklist">${(p.checks||[]).map(c=>`<div class="check-row"><span class="check-dot ${c.done?'done':''}" aria-label="${c.done?'완료':'미완료'}">${c.done?'✓':''}</span><span>${esc(c.text)}</span></div>`).join('')}</div><div class="story-meta">${tag(p.due||'기한 미정')}${tag(p.status||'계획','green')}</div></div></article>`;}).join('')}</div>`:empty('승진 계획을 추가해 주세요.','실제 팀원을 선택하고 목표 역할 · 기한 · 준비 체크리스트를 기록합니다.');}
function renderOverview(){const t=totals(),r=recruiting(),cb=callbackSummary(),g=draft.goals||{};return `<div class="overview-hero"><div><span class="eyebrow" style="color:#b7d0ff">${esc(monthName())} · ${esc(draft.teamName||'Presence')}</span><h2 style="margin-top:13px">${esc(draft.headline||'한 달의 기록을, 다음 성장으로.')}</h2><p>${esc((draft.wins||[])[0]?.title||'이달의 성과와 배움을 기록해 주세요.')}</p></div><div class="hero-score"><span>TEAM SALES</span><b>${fmt(t.sales)}</b></div></div><div class="overview-grid">${[['AVG',avgFmt(t.avg),'필드 '+fmt(t.days)+'일'],[t.incomeComplete===false?'확인된 인컴':'TEAM INCOME',money(t.incomeComplete===false?knownIncome():t.income),t.incomeComplete===false?`미입력 급여 기록 ${missingIncome()}개`:'입력 급여 주차 합계'],['REJECTION',pct(t.rate),'리젝은 리섭 차감 후 기준'],['RECRUITING',`${fmt(r.starters)}명`,`부킹 ${fmt(r.booked)} · 쇼업 ${fmt(r.showup)}`],['CALLBACK',pct(cb.rate),`${cb.submitted}회 / ${cb.days}일 · 미입력 ${cb.missing}명`],['LEARNING',`${(draft.learning||[]).length}개`,(draft.learning||[])[0]?.title||'학습 기록 미입력']].map(([title,note,sub])=>`<div class="overview-tile"><h3>${title}</h3><b>${esc(note)}</b><p>${esc(sub)}</p></div>`).join('')}</div><div class="goal-ribbon"><b>${nextMonthName()}<br>NEXT GOAL</b><div><p>세일즈 ${fmt(g.sales)} · AVG ${avgFmt(g.avg)} · 스타터 ${fmt(g.recruit)}명 · 콜백 ${pct(g.callback)}</p><p style="margin-top:8px">${esc(g.focus||'다음 달 집중 과제를 기록해 주세요.')}</p>${g.actions?`<p style="margin-top:8px">${esc(g.actions)}</p>`:''}</div></div>`;}
const renderers={sales:renderSales,weekly:renderWeekly,income:renderIncome,recruit:()=>renderRecruit(),rank:()=>renderRecruit(true),qc:renderQC,wins:()=>renderStories('wins'),challenges:()=>renderStories('challenges'),callback:renderCallback,learning:renderLearning,ic:renderIC,tree:renderTree,promotion:renderPromotion,overview:renderOverview};

function renderCanvas(){if(!draft)return;const v=view();$('#canvas').innerHTML=`<article class="slide" aria-label="${esc(v.title)}"><header class="slide-head"><div><span class="slide-kicker">${String(v.c+1).padStart(2,'0')} · ${chapters[v.c][0]}</span><h1>${esc(v.title)}</h1><p class="slide-sub">${esc(desc[v.id])}</p></div><div class="slide-logo">Presence<small>${esc(month)} · TEAM RECAP</small></div></header><div class="slide-content">${renderers[v.id]()}</div><footer class="slide-foot"><span>${esc(draft.teamName||'Presence')} · ${esc(monthName())}${draft.leader?` · ${esc(draft.leader)}`:''}</span><span>리젝은 리섭 차감 후 기준 · ${String(page+1).padStart(2,'0')} / ${views.length}</span></footer></article>`;$('#pageCount').textContent=`${String(page+1).padStart(2,'0')} / ${views.length} · ${v.title}`;$('#presentCount').textContent=`${page+1} / ${views.length}`;schedulePresentationFit();}
function render(){if(!draft)return;const v=view();$('#month').value=month;if($('#editorLink'))$('#editorLink').href=`recap-keynote.html?month=${encodeURIComponent(month)}`;$('#docName').textContent=`${monthName()} · ${draft.teamName||'Team'} Recap${readOnly?' · 열람':' · 작성 및 저장'}`;$('#chapters').innerHTML=chapters.map(([en,ko],i)=>`<button class="chapter ${i===v.c?'active':''}" data-action="chapter" data-index="${i}" ${i===v.c?'aria-current="page"':''}><span class="no">${String(i+1).padStart(2,'0')}</span><span><b>${ko}</b><small>${en}</small></span></button>`).join('');$('#chapterLabel').textContent=`${String(v.c+1).padStart(2,'0')} / ${chapters[v.c][0]}`;$('#subnav').innerHTML=views.map((v,i)=>({...v,index:i})).filter(x=>x.c===v.c).map(x=>`<button data-action="page" data-index="${x.index}" class="${x.index===page?'active':''}" ${x.index===page?'aria-current="page"':''}>${x.title}</button>`).join('');renderCanvas();renderEditor();renderNotice();status();document.querySelectorAll('[data-action="save"],[data-action="edit"],[data-action="publish"],[data-action="refresh"],[data-action="import"]').forEach(b=>b.disabled=readOnly);}
function renderNotice(){const entries=[...noticeMessages];if(readOnly)entries.unshift(params.has('published')?'게시된 발표본을 열람하고 있습니다.':'저장된 리캡을 열람하고 있습니다.');$('#notice').hidden=!entries.length;$('#notice').innerHTML=entries.map(esc).join('<br>')+(readOnly?'<button data-action="open-draft">작성 및 저장으로</button>':'');}
function status(message){$('#saveStatus').textContent=message||(readOnly?(params.has('published')?'게시된 발표본':'저장된 리캡 · 열람 전용'):saving?'클라우드에 저장 중…':dirty?'수정됨 · 이 기기에 임시 보관':!draft?.revision?'워크북으로 불러온 새 리캡 · 아직 저장하지 않았습니다.':'클라우드 저장본 · '+(draft?.updatedAt?new Date(draft.updatedAt).toLocaleString('ko-KR',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'저장 전'));}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('on');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('on'),4500);}
function changed(){if(readOnly)return;dirty=true;changeVersion++;draft.updatedAt=Date.now();try{localStorage.setItem(backupKey(),JSON.stringify({draft,at:Date.now(),baseRevision:draft.revision||0}));}catch{status('수정됨 · 기기 임시 저장 실패, 클라우드에 저장해 주세요');}status();}
function bindField(path,label,type='textarea',help=''){const value=path.split('.').reduce((o,k)=>o?.[k],draft);return `<label>${esc(label)}${type==='textarea'?`<textarea data-bind="${path}">${esc(value||'')}</textarea>`:`<input data-bind="${path}" type="${type}" value="${esc(value??'')}" ${type==='number'?'min="0" step="any"':''}>`}${help?`<small class="mini">${esc(help)}</small>`:''}</label>`;}
function editorList(type,title,caption){const rows=records(type);return `<section class="editor-section"><h3>${title}</h3><div class="stack">${rows.map((r,i)=>`<div class="editor-list"><button data-action="edit-record" data-kind="${type}" data-id="${esc(r.id)}">${esc(caption?.(r)||r.title||r.name||`${title} ${i+1}`)}</button><button data-action="delete-record" data-kind="${type}" data-id="${esc(r.id)}" aria-label="${esc(r.title||r.name||title)} 삭제">×</button></div>`).join('')}</div><button class="primary" data-action="add-record" data-kind="${type}">＋ ${title} 추가</button></section>`;}
function renderEditor(){if(!draft||readOnly)return;const type=view().id;let content=`<section class="editor-section"><h3>리캡 문서</h3>${bindField('teamName','팀 이름','text')}${bindField('leader','작성자 · 리더','text')}${bindField('headline','이달의 한 문장','text')}<p class="mini">변경 내용은 이 기기에 임시 보관됩니다. 상단 저장으로 클라우드에 저장하세요.</p></section>`;
  if(['sales','weekly','income'].includes(type))content+=`<section class="editor-section"><h3>워크북 수치</h3><p class="mini">세일즈 · 필드 · 급여 · 리젝 수치는 워크북을 기준으로 불러옵니다.</p><button data-action="refresh">워크북 수치 새로 불러오기</button>${bindField('notes.sales','세일즈 회고')}</section>`;
  if(['recruit','rank'].includes(type))content+=editorList('recruiting','리쿠르팅 실적')+`<section class="editor-section">${bindField('notes.recruit','리쿠르팅 회고')}</section>`;
  if(type==='qc')content+=`<section class="editor-section">${bindField('qc.startCount','월초 인원','number')}${bindField('qc.retentionWin','유지에 도움이 된 WIN')}${bindField('qc.trainingHow','교육 · 유지 활동 HOW')}</section>`+editorList('events','In · Out 기록');
  if(type==='wins')content+=editorList('wins','성과');
  if(type==='challenges')content+=editorList('challenges','개선 액션');
  if(type==='callback')content+=`<section class="editor-section"><h3>콜백싯 입력 · 팀 지정</h3><p class="mini">표에서 제출 횟수를 입력하세요. 0회와 미입력은 구분합니다. 팀 지정은 이달의 콜백 그룹에 적용하며 팀 트리와 별도로 보존합니다.</p>${(draft.members||[]).map(m=>`<button data-action="member-team" data-id="${esc(m.id)}">${esc(m.name)} · ${esc(m.team||'팀 미지정')}</button>`).join('')}</section>`;
  if(type==='learning')content+=editorList('learning','학습 · 실행 계획',r=>`${r.track} · ${r.title||r.period}`);
  if(type==='ic')content+=`<section class="editor-section"><h3>IC 성장 플랜</h3>${icMembers().map(m=>`<button data-action="ic-plan" data-id="${esc(m.id)}">${esc(m.name)} · 역량 & 3일 플랜</button>`).join('')}<button class="primary" data-action="ic-plan">＋ 팀원 성장 플랜</button><p class="mini">5개 역량을 각각 0~5로 평가합니다. 빈칸은 미평가로 유지합니다. 첫 5일 실적은 실제 날짜별 자료가 있는 경우에만 표시됩니다.</p></section>`;
  if(type==='tree')content+=`<section class="editor-section"><h3>이달의 팀 트리</h3><button class="primary" data-action="tree-add">＋ 팀원 추가</button>${(draft.tree||[]).map(n=>`<div class="editor-list"><button data-action="tree-edit" data-id="${esc(n.id)}">${esc(n.name)}${n.planned?' · 추가 예정':''}</button>${n.planned?`<button data-action="tree-delete" data-id="${esc(n.id)}" aria-label="${esc(n.name)} 예정 노드 삭제">×</button>`:''}</div>`).join('')}<button data-action="reload-tree">워크북 원본 다시 불러오기</button><p class="mini">팀 트리는 월별로 보존합니다. 원본 다시 불러오기는 이달에 편집한 관계와 추가 예정 노드를 초기화합니다.</p></section>`;
  if(type==='promotion')content+=editorList('promotions','승진 계획',r=>`${allPeople().find(m=>m.id===r.memberId)?.name||'팀원 확인 필요'} → ${r.targetRole||'목표 역할'}`);
  if(type==='overview')content+=`<section class="editor-section"><h3>${nextMonthName()} 목표</h3>${bindField('goals.sales','세일즈 목표','number')}${bindField('goals.avg','AVG 목표','number')}${bindField('goals.recruit','스타터 목표','number')}${bindField('goals.callback','콜백싯 제출률 목표 (%)','number')}${bindField('goals.focus','집중 과제')}${bindField('goals.actions','실행 계획')}</section>`;
  $('#editor').innerHTML=content;
}
function allPeople(){const map=new Map();[...(draft.roster||[]),...(draft.members||[])].forEach(m=>{if(m.id)map.set(m.id,m)});return [...map.values()].sort((a,b)=>String(a.name).localeCompare(String(b.name),'ko'));}
function openModal(title,body,submit,button='적용'){dialogOrigin=document.activeElement;$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=body;$('#dialogForm footer').hidden=!submit;$('#dialogForm button[type="submit"]').textContent=button;pendingModal=submit;$('#dialog').showModal();requestAnimationFrame(()=>$('#dialogBody input, #dialogBody select, #dialogBody textarea, #dialogBody button, #dialog .dialog-head button')?.focus());}
function restoreDialogFocus(){if(dialogOrigin?.isConnected&&!dialogOrigin.closest('[hidden]'))dialogOrigin.focus();else (editing?$('#inspector [data-action="close-edit"]'):$('[data-action="present"]'))?.focus();}
function closeModal(){$('#dialog').close();pendingModal=null;restoreDialogFocus();}
function field(name,label,value='',type='text',opts={}){const attrs=`name="${esc(name)}" ${opts.required?'required':''}`;let control;if(type==='select')control=`<select ${attrs}>${(opts.options||[]).map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`;}).join('')}</select>`;else if(type==='textarea')control=`<textarea ${attrs}>${esc(value)}</textarea>`;else control=`<input ${attrs} type="${type}" value="${esc(value??'')}" ${type==='number'?`min="${opts.min??0}" ${opts.max!=null?`max="${opts.max}"`:''} step="${opts.step??1}"`:''}>`;return `<label class="${opts.wide?'span2':''}">${esc(label)}${control}${opts.help?`<small class="hint">${esc(opts.help)}</small>`:''}</label>`;}
function confirmAction(title,body,action,button='계속'){openModal(title,`<p class="form-intro">${esc(body)}</p>`,async()=>{await action();return true;},button);}
const statusOptions=['계획','진행 중','완료','보류'];
function editRecord(kind,recordId){if(readOnly||!draft)return;const original=records(kind).find(r=>r.id===recordId)||{id:newId()};const item=kind==='recruiting'?{...original,booked:original.booking??original.booked,starters:original.starter??original.starters}:original;let fields='',title='내용 편집';
  if(kind==='wins'){title='성과 & 성공 요인';fields=field('title','성과 제목',item.title,'text',{required:true,wide:true})+field('win','WIN · 어떤 성과가 있었나요?',item.win,'textarea',{wide:true})+field('how','HOW · 어떻게 만들었나요?',item.how,'textarea',{wide:true})+field('next','NEXT · 무엇을 반복할까요?',item.next,'textarea',{wide:true});}
  if(kind==='challenges'){title='챌린지 & 개선 액션';fields=field('title','개선 과제',item.title,'text',{required:true,wide:true})+field('cause','원인',item.cause,'textarea',{wide:true})+field('action','개선 액션',item.action,'textarea',{wide:true})+field('result','결과 · 확인 방법',item.result,'textarea',{wide:true})+field('owner','담당자',item.owner)+field('due','기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='events'){title='팀원 In · Out';fields=field('name','팀원 이름',item.name,'text',{required:true})+field('date','일자',item.date,'date')+field('type','구분',item.type||'In','select',{options:['In','Quit','Cut','Out · 확인 필요']})+field('owner','담당자',item.owner)+field('reason','사유',item.reason,'textarea',{wide:true})+field('action','후속 액션',item.action,'textarea',{wide:true})+field('status','진행 상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='learning'){title='학습 & 성장 계획';fields=field('track','분야',item.track||'IC','select',{options:['IC','트레이너','네트워킹']})+field('period','구분',item.period||'지난달 회고','select',{options:['지난달 회고','다음달 계획']})+field('title','제목',item.title,'text',{required:true,wide:true})+field('action','실행 내용 · 방법',item.action,'textarea',{wide:true})+field('result','배운 점 · 기대 결과',item.result,'textarea',{wide:true})+field('owner','담당자',item.owner)+field('due','기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions});}
  if(kind==='recruiting'){title='리쿠르팅 실적';fields=field('name','팀원',item.name,'select',{required:true,wide:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.name,`${m.name} · ${m.role||''}`])]})+field('booked','부킹',item.booked??0,'number')+field('showup','쇼업',item.showup??0,'number')+field('starters','스타터',item.starters??0,'number');}
  if(kind==='promotions'){title='승진 계획';fields=field('memberId','팀원',item.memberId,'select',{required:true,wide:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.id,`${m.name} · ${m.role||''}`])]})+field('targetRole','목표 역할',item.targetRole,'text',{required:true})+field('due','목표 기한',item.due,'date')+field('status','상태',item.status||'계획','select',{options:statusOptions})+field('action','준비 액션 · 마일스톤',item.action,'textarea',{wide:true})+field('checklist','체크리스트 · 한 줄에 하나', (item.checks||[]).map(c=>`${c.done?'[x]':'[ ]'} ${c.text}`).join('\n'),'textarea',{wide:true,help:'완료한 항목은 [x], 준비 중인 항목은 [ ]로 시작해 주세요.'});}
  openModal(title,`<div class="form-grid">${fields}</div>`,data=>{const out={...item,...data};if(kind==='recruiting'){for(const k of ['booked','showup','starters'])out[k]=number(data[k]);if(out.showup>out.booked||out.starters>out.showup)throw new Error('부킹 ≥ 쇼업 ≥ 스타터가 되도록 수치를 확인해 주세요.');out.booking=out.booked;out.starter=out.starters;const other=records(kind).find(r=>r.id!==out.id&&r.name===out.name);if(other)throw new Error('이 팀원의 실적이 이미 있습니다. 기존 기록을 편집해 주세요.');}if(kind==='promotions'){out.checks=data.checklist.split('\n').map(t=>t.trim()).filter(Boolean).map(t=>({text:t.replace(/^\[[ xX]\]\s*/,''),done:/^\[[xX]\]/.test(t)}));delete out.checklist;}const rows=[...records(kind)];const i=rows.findIndex(r=>r.id===item.id);if(i<0)rows.push(out);else rows[i]=out;setRecords(kind,rows);changed();render();return true;});
}
function memberTeam(memberId){const member=draft.members.find(m=>m.id===memberId);if(!member)return;openModal(`${member.name} · 팀 지정`,field('team','이달의 팀 이름',member.team||'','text',{required:true}),data=>{member.team=data.team.trim();const person=(draft.roster||[]).find(m=>m.id===memberId);if(person)person.team=member.team;member.teamManual=true;changed();render();return true;});}
function icPlan(memberId){if(readOnly||!draft)return;const member=allPeople().find(m=>m.id===memberId);if(!member){openModal('성장 플랜 팀원 선택',field('memberId','팀원','','select',{required:true,options:[['','팀원 선택'],...allPeople().map(m=>[m.id,`${m.name} · ${m.role||''}`])]}),data=>{closeModal();icPlan(data.memberId);return false;});return;}const p=draft.icPlans?.[member.id]||{};openModal(`${member.name} · IC 성장 플랜`,`<p class="form-intro">역량은 0~5로 평가합니다. 판단하지 않은 항목은 비워 두세요.</p><div class="form-grid">${abilities.map(([key,label])=>field(key,label,p[key],'number',{max:5,help:key==='pitch'?'Tone of Voice · Body Language':''})).join('')}${field('focus','집중 역량',p.focus,'textarea',{wide:true})}${[1,2,3].map(n=>field(`day${n}`,`DAY ${n} · 목표와 실행`,p[`day${n}`],'textarea',{wide:true})).join('')}</div>`,data=>{abilities.forEach(([key])=>data[key]=number(data[key]));draft.icPlans??={};draft.icPlans[member.id]=data;changed();render();return true;});}
function treeAdd(parentId=''){if(readOnly||!draft)return;openModal('어떤 팀원을 추가할까요?',`<div class="choice-grid step-enter"><button type="button" class="choice" data-action="tree-choice-existing" data-id="${esc(parentId)}"><b>기존 팀원 추가</b><span>워크북 팀원을 선택하고<br>연결할 리더를 지정합니다.</span></button><button type="button" class="choice planned" data-action="tree-choice-planned" data-id="${esc(parentId)}"><b>New IC 추가 예정</b><span>이름과 리더를 지정해<br>다음 팀 구성을 계획합니다.</span></button></div>`,null);}
function treePeople(){return M.workbookTree(liveSource?.state||{},draft.roster||[]).filter(m=>!m.planned);}
function treeEditor(nodeId,planned=false,parentId=''){const node=(draft.tree||[]).find(n=>n.id===nodeId),isPlanned=node?node.planned:planned;const selectedParent=node?.parent||parentId;closeModal();const parents=(draft.tree||[]).filter(n=>n.id!==nodeId);const people=treePeople();if(node&&!node.planned&&!people.some(p=>p.id===(node.memberId||node.id)))people.push({...node,id:node.memberId||node.id});openModal(node?'팀원 연결 편집':isPlanned?'New IC 추가 예정':'기존 팀원 추가',`<div class="form-grid">${isPlanned?field('name','예정 팀원 이름',node?.name||'New IC','text',{required:true,wide:true}):field('memberId','기존 팀원',node?.memberId||node?.id||'','select',{required:true,wide:true,options:node?[[node.memberId||node.id,`${node.name} · ${node.role||''}`]]:[['','팀원 선택'],...people.map(m=>[m.id,`${m.name} · ${m.role||''}`])]})}${field('parent','연결할 리더',selectedParent,'select',{wide:true,options:[['','최상위에 배치'],...parents.map(n=>[n.id,`${n.name} · ${n.role||''}`])]})}</div><p class="form-intro" style="margin-top:18px">TL 이외의 트레이너에게도 연결할 수 있습니다. 월별 리캡의 팀 트리만 바뀝니다.</p>`,data=>{const actual=isPlanned?null:people.find(m=>m.id===data.memberId);if(!isPlanned&&!actual)throw new Error('기존 팀원을 선택해 주세요.');const existing=node||(!isPlanned?(draft.tree||[]).find(n=>n.id===actual.id||n.memberId===actual.id||n.name===actual.name):null);const next={...(existing||{}),id:existing?.id||(isPlanned?newId():actual.id),name:isPlanned?data.name.trim():actual.name,role:isPlanned?'IC':actual.role,team:isPlanned?'':actual.team,planned:isPlanned,parent:data.parent||null};if(actual)next.memberId=actual.id;let cursor=next.parent;const seen=new Set([next.id]);while(cursor){if(seen.has(cursor))throw new Error('팀 관계가 순환하지 않도록 리더를 다시 선택해 주세요.');seen.add(cursor);cursor=(draft.tree||[]).find(n=>n.id===cursor)?.parent;}draft.tree??=[];const i=draft.tree.findIndex(n=>n.id===next.id);if(i<0)draft.tree.push(next);else draft.tree[i]=next;changed();render();return true;});}

function validateDraft(candidate){if(candidate&&typeof candidate==='object'){for(const key of ['members','tree','roster','weeks','events','wins','challenges','learning','promotions']){if(!Array.isArray(candidate[key]))throw new Error(key+' 항목의 목록 형식을 확인해 주세요.');if(candidate[key].some(row=>!row||typeof row!=='object'||Array.isArray(row)))throw new Error(key+' 항목의 내용 형식을 확인해 주세요.');}for(const key of ['callbacks','qc','icPlans','goals','notes'])if(!candidate[key]||typeof candidate[key]!=='object'||Array.isArray(candidate[key]))throw new Error(key+' 항목의 형식을 확인해 주세요.');if(!Array.isArray(candidate.recruiting)&&(!candidate.recruiting||!Array.isArray(candidate.recruiting.rows)))throw new Error('리쿠르팅 목록 형식을 확인해 주세요.');for(const p of candidate.promotions)if(!Array.isArray(p.checks)||p.checks.some(c=>!c||typeof c.text!=='string'||typeof c.done!=='boolean'))throw new Error('프로모션 체크리스트 형식을 확인해 주세요.');for(const p of Object.values(candidate.icPlans))if(!p||typeof p!=='object'||Array.isArray(p))throw new Error('IC 성장 플랜 형식을 확인해 주세요.');}if(!candidate||candidate.version!==1||!/^\d{4}-\d{2}$/.test(candidate.month||'')||!Array.isArray(candidate.members)||!Array.isArray(candidate.tree))throw new Error('지원하는 Team Recap JSON 형식이 아닙니다.');if(M.validate){const result=M.validate(candidate);if(result===false)throw new Error('리캡 데이터 형식을 확인해 주세요.');if(Array.isArray(result)&&result.length)throw new Error(result.join('\n'));if(result?.ok===false)throw new Error((result.errors||['리캡 데이터 검증 실패']).join('\n'));}return candidate;}
async function makeLoaded(result){liveSource=result;noticeMessages=result.warnings||[];if(readOnly){const snapshot=params.has('published')?(result.published?.keynote||result.published?.snapshot||result.published?.draft||result.published):result.saved;if(!snapshot)throw new Error(params.has('published')?'이달에 게시된 발표본이 없습니다.':'이달에 저장된 리캡이 없습니다. 작성 및 저장 페이지에서 먼저 저장해 주세요.');return M.makeDraft({},month,snapshot);}if(result.saved)return M.makeDraft(result.state,month,result.saved.draft||result.saved);return M.makeDraft(result.state,month,result.legacy);}
async function loadMonth(next){const token=++loadToken;month=next;draft=null;$('#editor').innerHTML='';document.querySelectorAll('[data-action="save"],[data-action="edit"]').forEach(b=>b.disabled=true);$('#month').value=month;$('#canvas').innerHTML='<div class="slide"><div class="empty"><strong>리캡을 불러오는 중…</strong><span>월별 리캡 기록을 확인하고 있습니다.</span></div></div>';status('월별 기록 불러오는 중…');try{const result=await (isViewer?api.read(month,params.has('published')):api.load(month));if(token!==loadToken)return;draft=await makeLoaded(result);if(token!==loadToken)return;draft.month=month;draft.callbacks??={};draft.qc??={};draft.goals??={};draft.notes??={};draft.icPlans??={};dirty=false;const url=new URL(location.href);url.searchParams.set('month',month);history.replaceState(null,'',url);render();if(!readOnly){let backup;try{backup=JSON.parse(localStorage.getItem(backupKey())||'null');}catch{}if(backup?.draft&&backup.draft.month===month&&Number(backup.at)>Number(draft.updatedAt||0)){confirmAction('이 기기에 저장된 수정본이 있습니다.','클라우드 저장 이후 편집한 내용이 이 기기에 남아 있습니다. 복구하면 현재 리캡에 적용되며, 클라우드에는 저장 버튼을 눌러야 반영됩니다.',()=>{draft=validateDraft(backup.draft);dirty=true;render();toast('기기 수정본을 복구했습니다.');},'수정본 복구');}}if(params.has('present')&&!presenting)setPresent(true);}catch(error){noticeMessages=[error.message||'리캡을 불러오지 못했습니다.'];$('#canvas').innerHTML=`<div class="slide">${empty('리캡을 불러오지 못했습니다.',error.message||'연결 상태를 확인해 주세요.','retry-load')}</div>`;renderNotice();status('불러오기 실패 · 다시 시도해 주세요');}}
async function save(){if(!draft||readOnly||saving)return false;try{validateDraft(draft);saving=true;status();const savingDraft=draft,sent=copy(draft),sentVersion=changeVersion,revision=Number(draft.revision)||0;const saved=await api.save(sent,revision);if(draft!==savingDraft){toast(`${sent.month} 리캡을 저장했습니다.`);return true;}draft.revision=saved?.revision??saved?.draft?.revision??revision+1;if(changeVersion===sentVersion){draft.updatedAt=saved?.updatedAt||saved?.draft?.updatedAt||Date.now();dirty=false;try{localStorage.removeItem(backupKey());}catch{}}else{changed();}toast('리캡을 클라우드에 저장했습니다.');return true;}catch(error){status('저장 실패 · 수정 내용은 이 기기에 보관');toast(error.message||'저장하지 못했습니다. 수정 내용은 유지됩니다.');noticeMessages=[error.message||'저장하지 못했습니다. 연결 상태를 확인한 뒤 다시 저장해 주세요.'];renderNotice();return false;}finally{saving=false;status();}}
async function refreshSource(treeOnly=false){if(readOnly||!draft)return;confirmAction(treeOnly?'워크북 원본 트리 다시 불러오기':'워크북 수치 새로 불러오기',treeOnly?'워크북의 현재 팀 관계를 다시 불러옵니다. 이달에 수동으로 변경한 연결과 추가 예정 노드는 초기화됩니다.':'최신 워크북의 세일즈 · 필드 · 급여 · 팀원 정보를 다시 불러옵니다. 작성한 회고와 계획, 콜백싯 입력, 팀 트리는 보존합니다.',async()=>{const result=await api.load(month);const fresh=await M.makeDraft(result.state,month);if(treeOnly)draft.tree=copy(fresh.tree||[]);else{const oldCallbacks=draft.callbacks||{},oldMembers=draft.members||[],callbacks={};(fresh.members||[]).forEach(m=>{const old=oldMembers.find(o=>o.id===m.id)||oldMembers.find(o=>o.name===m.name);callbacks[m.id]=oldCallbacks[m.id]??(old?oldCallbacks[old.id]:null)??null;});const plans={};(fresh.members||[]).forEach(m=>{const old=oldMembers.find(o=>o.id===m.id)||oldMembers.find(o=>o.name===m.name);if(old?.teamManual){m.team=old.team;m.teamManual=true;const r=(fresh.roster||[]).find(r=>r.id===m.id);if(r)r.team=old.team;}if(draft.icPlans?.[m.id]||old&&draft.icPlans?.[old.id])plans[m.id]=draft.icPlans[m.id]||draft.icPlans[old.id];});draft.icPlans={...draft.icPlans,...plans};draft.members=fresh.members;draft.weeks=fresh.weeks;draft.roster=fresh.roster;draft.callbacks=callbacks;draft.sourceAt=fresh.sourceAt||Date.now();noticeMessages=result.warnings||[];}liveSource=result;changed();render();toast(treeOnly?'워크북 팀 관계를 다시 불러왔습니다.':'최신 워크북 수치를 불러왔습니다.');},'불러오기');}
function setEditing(value){if(readOnly||!draft)return;editing=value;document.body.classList.toggle('editing',value);$('[data-action="edit"]').setAttribute('aria-expanded',String(value));if(value)requestAnimationFrame(()=>$('#inspector [data-action="close-edit"]').focus());else $('[data-action="edit"]')?.focus();}
function navigate(index){page=(index+views.length)%views.length;render();if(editing)$('#inspector').scrollTop=0;}
function setPresent(value){presenting=value;if(value){setEditing(false);$('#docMenu').hidden=true;}document.body.classList.toggle('presenting',value);$('#presentControls').hidden=!value;renderCanvas();if(!value&&document.fullscreenElement)document.exitFullscreen?.().catch(()=>{});if(value)$('#presentControls button').focus();else $('[data-action="present"]').focus();}
async function openViewer(){if(!draft)return;if((dirty||!draft.revision)&&!await save())return;location.href=`recap-view.html?month=${encodeURIComponent(month)}`;}
async function action(button){const {action:act,id,kind,index}=button.dataset;if(readOnly&&!['page','chapter','prev','next','present','exit-present','fullscreen','menu','close-dialog','retry-load','open-draft','export','logout'].includes(act))return;switch(act){case 'save':await save();break;case 'page':navigate(Number(index));break;case 'chapter':navigate(views.findIndex(v=>v.c===Number(index)));break;case 'prev':navigate(page-1);break;case 'next':navigate(page+1);break;case 'edit':setEditing(!editing);break;case 'close-edit':setEditing(false);break;case 'present':if(isViewer)setPresent(true);else await openViewer();break;case 'exit-present':setPresent(false);break;case 'fullscreen':if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen?.();break;case 'menu':$('#docMenu').hidden=!$('#docMenu').hidden;button.setAttribute('aria-expanded',String(!$('#docMenu').hidden));if(!$('#docMenu').hidden)$('#docMenu button').focus();break;case 'close-dialog':closeModal();break;case 'retry-load':await loadMonth(month);break;case 'open-draft':{const url=new URL('recap-keynote.html',location.href);url.searchParams.set('month',month);location.href=url;break;}case 'add-record':editRecord(kind);break;case 'edit-record':editRecord(kind,id);break;case 'delete-record':confirmAction('기록 삭제','선택한 기록을 이달의 리캡에서 삭제합니다.',()=>{setRecords(kind,records(kind).filter(r=>r.id!==id));changed();render();},'삭제');break;case 'member-team':memberTeam(id);break;case 'ic-plan':icPlan(id);break;case 'tree-add':treeAdd(id);break;case 'tree-choice-existing':treeEditor(null,false,id);break;case 'tree-choice-planned':treeEditor(null,true,id);break;case 'tree-edit':treeEditor(id);break;case 'tree-delete':{const node=draft.tree.find(n=>n.id===id);if(!node?.planned)break;confirmAction('추가 예정 노드 삭제',`${node.name} 노드를 삭제합니다. 연결된 하위 노드는 상위 리더에게 연결됩니다.`,()=>{draft.tree.forEach(n=>{if(n.parent===id)n.parent=node.parent||null});draft.tree=draft.tree.filter(n=>n.id!==id);changed();render();},'삭제');break;}case 'refresh':await refreshSource();break;case 'reload-tree':await refreshSource(true);break;case 'export':{const blob=new Blob([JSON.stringify(draft,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`Presence-Team-Recap-${month}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('리캡 JSON 파일을 내보냈습니다.');break;}case 'import':$('#importFile').click();break;case 'publish':confirmAction('발표본 게시','현재 리캡을 저장하고 이달의 발표본으로 게시합니다. 이후 편집은 재게시하기 전까지 발표본에 반영되지 않습니다.',async()=>{if(!(await save()))return;await api.publish(copy(draft));toast('발표본을 게시했습니다.');},'저장하고 게시');break;case 'logout':if(dirty)confirmAction('로그아웃','현재 수정본은 이 기기에 남아 있습니다. 클라우드에 저장하려면 취소한 뒤 저장을 눌러 주세요.',async()=>{await api.logout();location.reload();},'로그아웃');else{await api.logout();location.reload();}break;}}

document.addEventListener('click',async e=>{const button=e.target.closest('button[data-action]');if(!button||button.disabled)return;try{if(!['menu','close-dialog'].includes(button.dataset.action)){$('#docMenu').hidden=true;$('[data-action="menu"]').setAttribute('aria-expanded','false');}await action(button);}catch(error){toast(error.message||'작업 중 오류가 발생했습니다.');}});
document.addEventListener('change',e=>{const path=e.target.dataset.bind;if(!path||!draft||readOnly)return;const parts=path.split('.');let obj=draft;parts.slice(0,-1).forEach(p=>{obj[p]??={};obj=obj[p]});const value=e.target.type==='number'?number(e.target.value):e.target.value;if(e.target.type==='number'&&value!=null&&(!Number.isFinite(value)||value<0)){e.target.setCustomValidity('0 이상의 숫자를 입력해 주세요.');e.target.reportValidity();return;}e.target.setCustomValidity('');obj[parts.at(-1)]=value;changed();renderCanvas();$('#docName').textContent=`${monthName()} · ${draft.teamName||'Team'} Recap`;});
document.addEventListener('input',e=>{const id=e.target.dataset.callback;if(!id||readOnly)return;const member=draft.members.find(m=>m.id===id);const value=number(e.target.value);if(value!=null&&(!Number.isInteger(value)||value<0||value>Number(member.days))){e.target.setCustomValidity(`0~${member.days} 사이의 정수를 입력해 주세요.`);e.target.reportValidity();return;}e.target.setCustomValidity('');draft.callbacks[id]=value;changed();renderCanvas();const target=[...document.querySelectorAll('[data-callback]')].find(el=>el.dataset.callback===id);if(target){target.replaceWith(e.target);e.target.focus();}});
$('#dialogForm').addEventListener('submit',async e=>{e.preventDefault();if(!pendingModal)return;const button=$('#dialogForm button[type="submit"]');button.disabled=true;try{const submit=pendingModal;const result=await submit(Object.fromEntries(new FormData(e.currentTarget)));if(result!==false&&pendingModal===submit)closeModal();}catch(error){let errorBox=$('#dialogError');if(!errorBox){errorBox=document.createElement('p');errorBox.id='dialogError';errorBox.className='notice';errorBox.setAttribute('role','alert');$('#dialogBody').append(errorBox);}errorBox.textContent=error.message||'입력 내용을 확인해 주세요.';errorBox.scrollIntoView({block:'nearest'});}finally{button.disabled=false;}});
$('#dialog').addEventListener('cancel',()=>{pendingModal=null;requestAnimationFrame(restoreDialogFocus);});
$('#month').addEventListener('change',e=>{const next=e.target.value;if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(next)){e.target.value=month;return;}if(dirty){e.target.value=month;confirmAction('다른 월 리캡 열기','현재 수정본은 이 기기에 임시 보관됩니다. 다른 기기에서도 확인하려면 먼저 클라우드에 저장해 주세요.',()=>loadMonth(next),'다른 월 열기');}else loadMonth(next);});
$('#importFile').addEventListener('change',async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;try{if(file.size>1024*1024)throw new Error('JSON 파일은 1MB 이하로 가져와 주세요.');const raw=JSON.parse(await file.text());if(raw.month&&raw.month!==month)throw new Error(`${raw.month} 리캡입니다. 해당 월을 먼저 선택해 주세요.`);const imported=validateDraft(raw.version===1?raw:M.importLegacyConfirmed(raw,liveSource?.state||{},month));if(imported.month!==month)throw new Error(`${imported.month} 리캡입니다. 해당 월을 먼저 선택한 뒤 가져와 주세요.`);confirmAction('리캡 JSON 가져오기',`${file.name} · ${imported.month} · 팀원 ${imported.members.length}명. 이 파일의 내용으로 현재 월의 편집본을 교체합니다. 클라우드에는 저장 버튼을 눌러야 반영됩니다.`,()=>{const revision=draft.revision;draft=copy(imported);draft.revision=revision;changed();render();toast('JSON 내용을 가져왔습니다.');},'가져오기');}catch(error){toast(error.message||'JSON 파일을 읽지 못했습니다.');}});
document.addEventListener('keydown',e=>{const typing=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='s'&&draft&&!readOnly){e.preventDefault();save();return;}if(e.key==='Escape'){if($('#dialog').open)return;if(presenting)setPresent(false);else if(editing)setEditing(false);else{$('#docMenu').hidden=true;$('[data-action="menu"]').setAttribute('aria-expanded','false');$('[data-action="menu"]').focus();}return;}if(!$('#docMenu').hidden&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){const buttons=[...$('#docMenu').querySelectorAll('button:not(:disabled)')],at=buttons.indexOf(document.activeElement);e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(at+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus();return;}if(!presenting||typing||$('#dialog').open)return;if(['ArrowRight','ArrowDown',' ','PageDown'].includes(e.key)){e.preventDefault();navigate(page+1);}if(['ArrowLeft','ArrowUp','PageUp'].includes(e.key)){e.preventDefault();navigate(page-1);}if(e.key==='Home'){e.preventDefault();navigate(0);}if(e.key==='End'){e.preventDefault();navigate(views.length-1);}});
let presentationFitFrame=0;
function schedulePresentationFit(){if(presentationFitFrame)cancelAnimationFrame(presentationFitFrame);presentationFitFrame=requestAnimationFrame(fitPresentation);}
function fitPresentation(){presentationFitFrame=0;const canvas=$('#canvas'),slide=canvas.querySelector('.slide');if(!canvas||!slide)return;if(!presenting||matchMedia('(max-width:760px)').matches){canvas.removeAttribute('style');slide.style.minHeight='';return;}const width=Math.min(1450,Math.max(320,window.innerWidth-44));canvas.style.width=width+'px';slide.style.minHeight=(width*9/16)+'px';const controls=$('#presentControls').getBoundingClientRect(),availableHeight=Math.max(160,controls.top-32),naturalHeight=Math.ceil(Math.max(canvas.scrollHeight,slide.offsetHeight)),scale=Math.min(1,(window.innerWidth-44)/width,availableHeight/naturalHeight);canvas.style.transform='translateX(-50%) scale('+scale+')';canvas.style.top=(16+Math.max(0,(availableHeight-naturalHeight*scale)/2))+'px';}
const presentationObserver=new ResizeObserver(schedulePresentationFit);presentationObserver.observe($('#canvas'));window.addEventListener('resize',schedulePresentationFit);document.addEventListener('fullscreenchange',schedulePresentationFit);document.fonts?.ready.then(schedulePresentationFit);$('#canvas').addEventListener('load',schedulePresentationFit,true);
let touchStart=null;$('#canvas').addEventListener('touchstart',e=>{if(presenting&&e.touches.length===1)touchStart={x:e.touches[0].clientX,y:e.touches[0].clientY};},{passive:true});$('#canvas').addEventListener('touchend',e=>{if(!touchStart||!presenting)return;const t=e.changedTouches[0],dx=t.clientX-touchStart.x,dy=t.clientY-touchStart.y;touchStart=null;if(Math.abs(dx)>75&&Math.abs(dx)>Math.abs(dy)*1.5)navigate(page+(dx<0?1:-1));},{passive:true});
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});
window.addEventListener('offline',()=>status('오프라인 · 수정 내용은 이 기기에 보관'));
window.addEventListener('online',()=>{status();toast('연결되었습니다. 저장 버튼으로 클라우드에 반영하세요.');});
async function enter(candidate){const permitted=typeof allowed==='function'?await allowed(candidate):true;if(!permitted)throw new Error('팀 리캡에 접근할 권한이 없습니다.');user=candidate;$('#login').hidden=true;$('#app').hidden=false;await loadMonth(month);}
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();const button=e.currentTarget.querySelector('button');button.disabled=true;$('#loginMsg').textContent='로그인 확인 중…';try{const candidate=await api.login($('#loginId').value.trim(),$('#loginPw').value);$('#loginPw').value='';await enter(candidate);}catch(error){$('#loginMsg').textContent=error.message||'로그인하지 못했습니다. 아이디와 비밀번호를 확인해 주세요.';}finally{button.disabled=false;}});
async function start(){if(!isViewer&&(params.has('published')||params.has('present')))return;document.querySelectorAll('.archive-link,.login-card .text-link').forEach(a=>a.href='recap-library.html');if(!isViewer){$('[data-action="present"]').textContent='열람';}else{const link=$('#editorLink');if(link)link.href=`recap-keynote.html?month=${encodeURIComponent(month)}`;}try{api=typeof gateway==='function'?await gateway():gateway;const fullscreen=document.createElement('button');fullscreen.dataset.action='fullscreen';fullscreen.textContent='전체화면';$('#presentControls').append(fullscreen);const candidate=await api.restore();if(candidate)await enter(candidate);else $('#loginMsg').textContent='Presence 계정으로 로그인해 주세요.';}catch(error){$('#loginMsg').textContent=error.message||'저장된 로그인을 확인하지 못했습니다. 다시 로그인해 주세요.';}}
start();
